def parse_rows(text: str) -> List[Tuple[str, str, str]]:
    """回答表の行（ID、項目、答え）の一覧。"""
    out = []
    for line in text.splitlines():
        m = ROW.match(line)
        if m:
            out.append((m.group(1), m.group(2), m.group(3)))
    return out


def make_variant(demo: str, variant: Dict) -> str:
    rows = {rid for rid, _item, _answer in parse_rows(demo)}
    unknown = sorted(set(variant["替え"]) - rows)
    if unknown:
        raise SystemExit(f"{variant['ファイル']}：回答表にない ID {unknown}")
    lines = demo.splitlines()
    out = []
    for i, line in enumerate(lines):
        if i == 0:
            out.append(line + f"・変種「{variant['名前']}」")
            continue
        m = ROW.match(line)
        if m and m.group(1) in variant["替え"]:
            line = f"| {m.group(1)} | {m.group(2)} | {variant['替え'][m.group(1)]} |"
        out.append(line)
        if i == 2:  # 1文目（テストで社長役のAIが使う〜）の後に、変種の説明を足す
            changed = "、".join(sorted(variant["替え"])) if variant["替え"] else "なし（デモの会社の回答表と同じ）"
            out.append("")
            out.append(f"この回答表は、デモの会社の回答表の変種です（{MARK}。{MADE_BY}）。変えた行：{changed}。")
    return "\n".join(out) + "\n"


def diff_rows(demo: str, variant_text: str) -> List[Tuple[str, str, str, str]]:
    """（ID、項目、デモの答え、変種の答え）の一覧。違う行だけ。"""
    before = {rid: (item, answer) for rid, item, answer in parse_rows(demo)}
    out = []
    for rid, item, answer in parse_rows(variant_text):
        if before[rid][1] != answer:
            out.append((rid, item, before[rid][1], answer))
    return out


